actions.script:
if (System.getProperty('pos.qa.disposable')!='true' || !ec.user.isInGroup('ADMIN')) {
    ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
if (ec.entity.find('mantle.party.Party').condition('partyId','POS_QA_A').disableAuthz().count()) {
    ec.web.response.setStatus(409);ec.web.sendJsonResponse([denied:true]);return
}
// Deterministic time-boundary tests invoke the real sweep explicitly; no scheduled worker races them.
ec.service.sync().name('update#moqui.service.job.ServiceJob').parameters([jobName:'zenith_PosIdleSessionSweep_5min',paused:'Y']).call()
def baseline=[modes:ec.entity.find('zenith.erp.pos.PosSalesMode').count(),sessionStatuses:ec.entity.find('moqui.basic.StatusItem').condition('statusTypeId','PosSession').count()]
ec.entity.makeDataLoader().location('component://zenith-erp-pos/PosQaTypes.xml').load()
ec.entity.makeDataLoader().location('component://zenith-erp-pos/PosQaFixture.xml').load()
// Reserve the first auto-numbered organization in this empty database. Live
// installs already have the protected org; never initialize this fixture there.
if (!ec.entity.find('mantle.party.Party').condition('partyId','100000').count()) {
    ec.service.sync().name('mantle.party.PartyServices.create#Organization').parameters([
        organizationName:'Disposable protected-org placeholder',roleTypeId:'OrgInternal']).call()
}
ec.service.sync().name('zenith.inventory.InventoryStockServices.adjust#AssetOnHand').parameters([organizationPartyId:'POS_QA_A',productId:'POS_QA_A_STOCK',quantityDiff:100,reason:'Disposable POS opening fixture',facilityId:'POS_QA_A_FAC']).call()
def demo=ec.entity.find('moqui.security.UserAccount').condition('userId','EX_JOHN_DOE').one()
['POS_QA_MANAGER','POS_QA_CASHIER','POS_QA_MANAGER_B'].each { id ->
    def user=ec.entity.find('moqui.security.UserAccount').condition('userId',id).one()
    ['currentPassword','passwordSalt','passwordHashType','passwordBase64'].each { user.set(it,demo.get(it)) }
    user.disabled='N';user.requirePasswordChange='N';user.update()
}
// The platform-admin migration probe needs a valid POS scope to traverse Pos.xml.
// This helper runs only in the newly initialized disposable synthetic database.
ec.user.setPreference('ACTIVE_ORGANIZATION','POS_QA_A')
ec.web.sendJsonResponse([initialized:true,normalSeedBaseline:baseline])

if (System.getProperty('pos.qa.disposable')!='true' || !(ec.user.username in ['john.doe','pos.qa'])) {ec.web.response.setStatus(403);return}
def catalog=ec.web.parameters.bundleJson
def upload=ec.web.parameters.bundleFile
if (upload && upload.metaClass.respondsTo(upload,'getInputStream')) catalog=upload.getInputStream().withCloseable { new String(it.readAllBytes(),'UTF-8') }
def input = new groovy.json.JsonSlurper().parseText(catalog ?: '{}')
if (!input.workspace?.code?.startsWith('cleanqa-') || !input.workspace?.adminEmail?.endsWith('@example.com') ||
    input.cashiers?.any { !it.username?.endsWith('@example.com') }) {ec.web.response.setStatus(400);return}
if (ec.web.parameters.markerMode) {
    if (!ec.user.isInGroup('ADMIN') || !(ec.web.parameters.markerMode in ['foreign','restore','expire'])) {ec.web.response.setStatus(403);return}
    def tenant=ec.entity.find('zenith.erp.saas.SaasTenant').condition('subdomain',input.workspace.code).one()
    if (!tenant || tenant.organizationPartyId=='100000') {ec.web.response.setStatus(400);return}
    def grant=ec.entity.find('zenith.erp.saas.SaasTenantConfig').condition('tenantId',tenant.tenantId).condition('configKey','MANUAL_PLAN_SUBSCRIPTION').one()
    def marker=ec.entity.find('zenith.erp.saas.SaasTenantConfig').condition('tenantId',tenant.tenantId).condition('configKey','MANUAL_PLAN_PERMANENT_SUBSCRIPTION').one()
    if (!grant || !marker) {ec.web.response.setStatus(400);return}
    if (ec.web.parameters.markerMode=='expire') ec.service.sync().name('zenith.saas.SaasAdminServices.expire#ManualPlan').parameters([tenantId:tenant.tenantId]).call()
    else marker.set('configValue',ec.web.parameters.markerMode=='restore' ? grant.configValue : 'WRONG_SYNTHETIC_SUB').update()
    ec.web.sendJsonResponse([changed:!ec.message.hasError()]);return
}
def r = ec.service.sync().name('zenith.saas.CleanWorkspaceServices.create#Workspace').parameters([
    bundleJson:catalog,apply:ec.web.parameters.apply == 'true',confirmationDigest:ec.web.parameters.confirmationDigest,
    adminPassword:ec.web.parameters.adminPassword,cashierOnePassword:ec.web.parameters.cashierOnePassword,cashierTwoPassword:ec.web.parameters.cashierTwoPassword]).call()
def errors=ec.message.errorsString;ec.message.clearErrors()
ec.web.sendJsonResponse([result:errors ? null : r?.result,errors:errors ?: ''])

if (System.getProperty('pos.qa.disposable')!='true' || ec.user.username!='pos.qa' || !ec.user.isInGroup('ZENITH_ADMIN') ||
        !['hybrid','view','manager','restore'].contains(ec.web.parameters.role) ||
        !ec.entity.find('moqui.security.UserAccount').condition('userId','POS_QA_CASHIER').condition('username','pos.cashier.qa').one()) {
    ec.web.sendJsonResponse([denied:true]); return
}
def groups=['ZENITH_CASHIER','ZENITH_INVENTORY_MGR','ZENITH_STORE_MGR','POS_QA_PRICE_VIEW']
boolean disabled=ec.artifactExecution.disableAuthz()
try {
    ec.entity.find('moqui.security.UserGroupMember').condition('userId','POS_QA_CASHIER').condition('userGroupId','in',groups).deleteAll()
    ec.service.sync().name('store#moqui.security.UserGroup').parameters([userGroupId:'POS_QA_PRICE_VIEW',description:'Disposable POS price read-only role']).call()
    ec.service.sync().name('store#moqui.security.ArtifactAuthz').parameters([artifactAuthzId:'POS_QA_PRICE_VIEW',userGroupId:'POS_QA_PRICE_VIEW',artifactGroupId:'Z_POS',authzTypeEnumId:'AUTHZT_ALLOW',authzActionEnumId:'AUTHZA_VIEW']).call()
    def selected=ec.web.parameters.role=='hybrid' ? groups[0..1] : (ec.web.parameters.role=='manager' ? [groups[2]] : (ec.web.parameters.role=='view' ? [groups[3]] : [groups[0]]))
    selected.each { group -> ec.entity.makeValue('moqui.security.UserGroupMember').setAll([userId:'POS_QA_CASHIER',userGroupId:group,fromDate:java.sql.Timestamp.valueOf('2020-01-01 00:00:00')]).create() }
} finally { if (!disabled) ec.artifactExecution.enableAuthz() }
ec.web.sendJsonResponse([updated:true])

if (System.getProperty('pos.qa.disposable')!='true' || ec.user.username!='pos.qa') { ec.web.sendJsonResponse([denied:true]); return }
def ids=new groovy.json.JsonSlurper().parseText(ec.web.parameters.transactionIdsJson ?: '[]')
if (!(ids instanceof List) || ids.size()!=4 || ids.unique(false).size()!=4) { ec.web.sendJsonResponse([denied:true]); return }
def bills=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId','in',ids).list()
if (bills.size()!=4 || bills.any { it.organizationPartyId!='POS_QA_A' || it.statusId!='PtCompleted' || !it.customerName?.startsWith('TZ QA ') }) {
    ec.web.sendJsonResponse([denied:true]); return
}
def instants=['2026-01-14T18:29:59.999Z','2026-01-14T18:30:00Z','2026-01-15T18:29:59.999Z','2026-01-15T18:30:00Z']
ids.eachWithIndex { id,index ->
    def stamp=java.sql.Timestamp.from(java.time.Instant.parse(instants[index]))
    bills.find { it.transactionId==id }.setAll([entryDate:stamp,completedDate:stamp]).update()
    ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',id).list().each { it.paymentDate=stamp;it.update() }
    ec.entity.find('zenith.erp.pos.PosItemPriceOverride').condition('transactionId',id).list().each { it.changeDate=stamp;it.update() }
    ec.entity.makeValue('zenith.erp.pos.PosTransactionAmendment').setAll([transactionId:id,amendedByPartyId:'POS_QA_MANAGER',
        amendmentDate:stamp,reason:'Synthetic timezone report fixture',changeType:'NOTE',oldGrandTotal:bills.find { it.transactionId==id }.grandTotal,newGrandTotal:bills.find { it.transactionId==id }.grandTotal,
        oldValue:'Synthetic report note',newValue:'Synthetic report note']).setSequencedIdPrimary().create()
}
ec.web.sendJsonResponse([prepared:true])

if (System.getProperty('pos.qa.disposable')!='true' || !['pos.qa','pos.b.qa'].contains(ec.user.username)) {
    ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
def session=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',ec.web.parameters.sessionId).one()
if (!session || session.organizationPartyId!=(ec.user.username=='pos.qa'?'POS_QA_A':'POS_QA_B') || session.statusId!='PsOpen') {
    ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
def minutes=(ec.web.parameters.minutes ?: '61').toString()
if (!['5','55','61'].contains(minutes)) {ec.web.response.setStatus(400);ec.web.sendJsonResponse([denied:true]);return}
session.lastActivityDate=new java.sql.Timestamp(ec.user.nowTimestamp.time-minutes.toLong()*60L*1000L)
session.update()
ec.web.sendJsonResponse([backdated:true])

if (System.getProperty('pos.qa.disposable')!='true' || ec.user.username!='pos.qa') {
    ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
def cart=ec.entity.find('zenith.erp.pos.PosTransaction')
    .condition('transactionId',ec.web.parameters.transactionId).one()
if (!cart || cart.organizationPartyId!='POS_QA_A' || cart.statusId!='PtCreated') {
    ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
def state = ec.web.parameters.legacyRegion == 'Y' ? 'LEGACY_GEO_TN' : null
cart.originRegionGeoId=state;cart.destinationRegionGeoId=ec.web.parameters.interstate=='Y' ? '27' : state;cart.update()
ec.web.sendJsonResponse([cleared:true])

if (System.getProperty('pos.qa.disposable')!='true' || ec.user.username!='pos.qa') {
    ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
def value=ec.web.parameters.org
if (!['POS_QA_A','POS_QA_B','NONE'].contains(value)) {
    ec.web.response.setStatus(400);ec.web.sendJsonResponse([denied:true]);return
}
ec.user.setPreference('ACTIVE_ORGANIZATION',value=='NONE'?null:value)
ec.web.sendJsonResponse([scope:value])

if(System.getProperty('pos.qa.disposable')!='true' || ec.user.username!='pos.qa') {
    ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
def bill=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',ec.web.parameters.transactionId).one()
if(!bill || bill.organizationPartyId!='POS_QA_A' || bill.statusId!='PtCompleted') {
    ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
def priorMillis=bill.entryDate.time
def mode=ec.web.parameters.mode
if(mode in ['early','late']) {
    def clock=mode=='early'?'00:30:00.000':'23:59:59.999'
    bill.entryDate=ec.l10n.parseTimestamp('2040-01-02 '+clock,'yyyy-MM-dd HH:mm:ss.SSS')
} else if(mode=='restore' && ec.web.parameters.originalMillis?.toString()==~ /[0-9]+/) {
    bill.entryDate=new java.sql.Timestamp(Long.parseLong(ec.web.parameters.originalMillis.toString()))
} else {ec.web.response.setStatus(400);ec.web.sendJsonResponse([denied:true]);return}
bill.update()
ec.web.sendJsonResponse([changed:true,priorMillis:priorMillis])
